const settings = $('Enrollment settings').first().json;

const text = (name, value = '', extra = {}) => ({ type: 'text', name, value, width: 260, height: 18, ...extra });
const checkbox = (name, label) => ({ type: 'checkbox', name, value: false, text: label, width: 160, height: 16 });

return $input.all().map(({ json: person }) => {
  const fullName = `${person.firstName} ${person.lastName}`;
  return {
    json: {
      employee_name: fullName,
      file_name: `Benefits enrollment ${settings.plan_year} - ${fullName}`,
      form_data: {
        company: settings.company,
        plan_year: settings.plan_year,
        deadline: settings.deadline,
        return_url: settings.return_url,
        first_name: person.firstName,
        // name and ID are locked so the returned form can be matched to the right person
        employee_name: text('employee_name', fullName, { lock: true }),
        employee_id: text('employee_id', String(person.id), { lock: true }),
        email: text('email', person.email),
        phone: text('phone', person.phone),
        department: text('department', person.company?.department ?? ''),
        job_title: text('job_title', person.company?.title ?? ''),
        // one entry per choice; the template loops over them so they form a single radio group
        medical_plan: ['Basic', 'Standard', 'Premium', 'Waive coverage'].map((plan) => ({
          option: { type: 'radio', name: 'medical_plan', value: plan, text: plan, width: 120, height: 16 },
        })),
        dental: checkbox('dental', 'Dental'),
        vision: checkbox('vision', 'Vision'),
        life_insurance: checkbox('life_insurance', 'Life insurance'),
        dependents: text('dependents', '', { width: 60 }),
        beneficiary_name: text('beneficiary_name'),
        signature_name: text('signature_name'),
        signature_date: text('signature_date', '', { width: 120 }),
      },
    },
  };
});

const fields = $input.first().json;
const value = (name) => fields[name]?.[0]?.value;
const plan = value('medical_plan');

return [{
  json: {
    employee_id: value('employee_id'),
    employee_name: value('employee_name'),
    benefits: {
      medical_plan: plan && plan !== 'Off' ? plan : 'Not chosen',
      dental: value('dental') === true,
      vision: value('vision') === true,
      life_insurance: value('life_insurance') === true,
      dependents: Number(value('dependents') || 0),
      beneficiary: value('beneficiary_name') ?? '',
    },
    signed_by: value('signature_name') ?? '',
    signed_on: value('signature_date') ?? '',
  },
}];
